class Solution {
public:
    int scoreOfParentheses(string s) {
        vector<int> st(1, 0);
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == '(') {
                st.push_back(0);
            } else {
                int inner = st.back();
                st.pop_back();
                st.back() += max(2 * inner, 1);
            }
        }
        return st[0];
    }
};
